JS_SNIPPET = """
  // Jewelry Category Metal Dropdowns (925 Silver & 18K Gold)
  window.toggleCategoryDropdown = function (key, e) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    const subMenu = document.getElementById('subcat-menu-' + key);
    const chevron = document.getElementById('chevron-' + key);
    if (!subMenu) return;
    const isHidden = subMenu.classList.contains('hidden');

    const prefix = key.startsWith('mob-') ? 'mob-' : 'desktop-';
    const otherKey = prefix + (key.endsWith('silver') ? 'gold' : 'silver');
    const otherMenu = document.getElementById('subcat-menu-' + otherKey);
    const otherChevron = document.getElementById('chevron-' + otherKey);

    if (isHidden) {
      subMenu.classList.remove('hidden');
      if (chevron) chevron.classList.add('rotate-180', 'text-[#61532E]');
      if (otherMenu) otherMenu.classList.add('hidden');
      if (otherChevron) otherChevron.classList.remove('rotate-180', 'text-[#61532E]');
    } else {
      subMenu.classList.add('hidden');
      if (chevron) chevron.classList.remove('rotate-180', 'text-[#61532E]');
    }
  };
"""

def update_html_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    changed = False
    if DESKTOP_OLD in content:
        content = content.replace(DESKTOP_OLD, DESKTOP_NEW)
        changed = True
    else:
        print(f"Warning: DESKTOP_OLD not found in {filepath}")

    if MOB_OLD in content:
        content = content.replace(MOB_OLD, MOB_NEW)
        changed = True
    else:
        print(f"Warning: MOB_OLD not found in {filepath}")

    if changed:
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f"Updated HTML: {filepath}")
    return changed

def update_js_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    if 'window.toggleCategoryDropdown' in content:
        print(f"toggleCategoryDropdown already in {filepath}")
        return True

    target = "window.closeCollectionsMenu = function () {"
    if target in content:
        parts = content.split(target)
        # Place JS_SNIPPET right before closeCollectionsMenu
        new_content = parts[0] + JS_SNIPPET + "\n  " + target + parts[1]
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(new_content)
        print(f"Updated JS: {filepath}")
        return True
    else:
        print(f"Warning: target not found in {filepath}")
        return False

def main():
    root = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
    html_dirs = ['jewellery-design-html', 'jewellery-design-html-dist']
    html_files = ['categories.html', 'index.html', 'offers.html', 'privacy.html', 'product.html', 'products.html', 'terms.html']

    for d in html_dirs:
        js_path = os.path.join(root, d, 'js', 'app.js')
        if os.path.exists(js_path):
            update_js_file(js_path)

        for hf in html_files:
            hp = os.path.join(root, d, hf)
            if os.path.exists(hp):
                update_html_file(hp)

    print("Completed menu categories upgrade!")

if __name__ == '__main__':
    main()

